let REPORT_SECURITY=null,REPORT_PUBLIC_KEY=null;const REPORT_ENCODER=new TextEncoder();
function reportB64(value){let bytes=value instanceof Uint8Array?value:new Uint8Array(value),binary='';for(let i=0;i<bytes.length;i++)binary+=String.fromCharCode(bytes[i]);return btoa(binary)}
