async function stageReportFile(file,purpose='financial'){let securityInfo=await ensureReportSecurity();if(file.size>securityInfo.max_upload_bytes)throw new Error(`O arquivo ${file.name} excede o limite permitido.`);let aesKey=await crypto.subtle.generateKey({name:'AES-GCM',length:256},true,['encrypt']),rawKey=await crypto.subtle.exportKey('raw',aesKey),wrappedKey=await crypto.subtle.encrypt({name:'RSA-OAEP'},REPORT_PUBLIC_KEY,rawKey),uploadId='';try{let init=await reportApi('/api/uploads/init',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:file.name,size:file.size,purpose,encrypted_key:reportB64(wrappedKey)})});uploadId=init.upload_id;let chunkBytes=Number(init.chunk_bytes)||securityInfo.upload_chunk_bytes,totalChunks=Number(init.total_chunks)||Math.ceil(file.size/chunkBytes);for(let index=0;index<totalChunks;index++){let start=index*chunkBytes,end=Math.min(file.size,start+chunkBytes),plain=await file.slice(start,end).arrayBuffer(),iv=crypto.getRandomValues(new Uint8Array(12)),aad=REPORT_ENCODER.encode(`cap-upload-v1|${uploadId}|${index}|${plain.byteLength}`),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:aad,tagLength:128},aesKey,plain);await reportApi(`/api/uploads/${uploadId}/chunk/${index}`,{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Chunk-IV':reportB64(iv),'X-Plain-Size':String(plain.byteLength)},body:cipher});await new Promise(resolve=>setTimeout(resolve,0))}await reportApi(`/api/uploads/${uploadId}/complete`,{method:'POST'});return uploadId}catch(error){if(uploadId)await discardReportUploads([uploadId]);throw error}}
