function fitWithin(node,minSize){node.style.fontSize='';node.style.maxWidth='';node.style.transform='';node.style.transformOrigin='';node.style.letterSpacing='';let parent=node.parentElement;if(!parent||!parent.clientWidth)return;let size=parseFloat(getComputedStyle(node).fontSize)||12,available;if(node.closest('.kpi')){let ps=getComputedStyle(parent);available=Math.max(40,parent.clientWidth-(parseFloat(ps.paddingLeft)||0)-(parseFloat(ps.paddingRight)||0))}else{let ps=getComputedStyle(parent);available=Math.max(40,parent.clientWidth-(parseFloat(ps.paddingLeft)||0)-(parseFloat(ps.paddingRight)||0))}node.style.display='block';node.style.maxWidth=available+'px';let guard=0;while(node.scrollWidth>available+1&&size>minSize&&guard++<70){size-=.3;node.style.fontSize=size+'px'}if(node.scrollWidth>available+1){node.style.letterSpacing='-.035em';let ratio=Math.max(.78,Math.min(1,available/node.scrollWidth));node.style.transform=`scaleX(${ratio})`;node.style.transformOrigin='left center'}}
